using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using SistemPengurusanKehadiran.Helpers;using SistemPengurusanKehadiran.Services;namespace SistemPengurusanKehadiran.Pages;public sealed partial class BackupRestorePage:Page{public BackupRestorePage(){InitializeComponent();Loaded+=(_,_)=>Refresh();}void Refresh(){var c=ServerConfigService.Instance.Load();ConfigStatus.Text=c==null?"CONFIG TIADA":$"CONFIG ADA · {c.BaseUrl} · token {(ServerConfigService.Instance.LoadToken()!=null?"dilindungi Windows":"tiada")}";}async void Backup_Click(object s,RoutedEventArgs e){var p=PickerHelper.CreateSavePicker(App.MainWindowInstance!);p.FileTypeChoices.Add("ZIP",new List<string>{".zip"});p.SuggestedFileName=$"SPK_Backup_{DateTime.Now:yyyyMMdd_HHmm}";var f=await p.PickSaveFileAsync();if(f==null)return;try{BackupService.Instance.Create(f.Path);Status.Text="Backup berjaya.";}catch(Exception ex){Status.Text="Backup gagal: "+ex.Message;}}async void Restore_Click(object s,RoutedEventArgs e){var p=PickerHelper.CreateOpenPicker(App.MainWindowInstance!);p.FileTypeFilter.Add(".zip");var f=await p.PickSingleFileAsync();if(f==null)return;try{BackupService.Instance.Restore(f.Path);Status.Text="Restore berjaya.";}catch(Exception ex){Status.Text="Restore gagal: "+ex.Message;}}async void Config_Click(object s,RoutedEventArgs e){var p=PickerHelper.CreateOpenPicker(App.MainWindowInstance!);p.FileTypeFilter.Add(".zip");var f=await p.PickSingleFileAsync();if(f==null)return;try{ServerConfigService.Instance.ImportZip(f.Path);if(ServerConfigService.Instance.IsReady(DatabaseService.Instance.SchoolId,out var reason)){AutoSyncService.Instance.SetEnabled(true);Status.Text="Server Config sedia. Auto Sync diaktifkan.";}else{Status.Text="Server Config diimport tetapi belum boleh sync: "+reason;}Refresh();}catch(Exception ex){Status.Text="Import config gagal: "+ex.Message;}}}
